AI Agent 基本架构用户问题 -&gt; LLM判断 -&gt; 是否需要工具 -&gt; 执行Tool -&gt;LLM总结结果创建Tools文件路径:tools/timeTool.jsexport function getTime(){
  let now = new Date()
  return now.toString()
}
创建Tool Router文件路径：tools/toolRouter.jsexport { getTime } from &#39;./timeTool.js&#39;
export async function runTool(name,args){
  if(name === &#39;getTime&#39;){
    return getTime()
  }
  return &#39;tool not found&#39;
}
让LLM决定是否调用工具文件路径：llm/chat.jsimport ollama from &#39;ollama&#39;

export async function askAgent(question) {
    let prompt = `你是一个AI助手，如果需要工具，请输出：
    TOOL:toolName
    例如 : 
    用户: 现在几点
    AI : 
    TOOL:getTime
    问题：${question}
    `
    let response = await ollama.chat({
        model:&#39;llama3&#39;,
        messages:[
            {role:&#39;user&#39;,content:prompt}
        ]
    })
    console.log(&#39;askAgent:&#39;,response.message.content)
    return response.message.content
}
执行工具文件路径：services/agentService.jsimport { askAgent } from &#34;../chat/askAgent.js&#34;;
import { runTool } from &#34;../tools/toolRouter.js&#34;;

export async function runAgent(question) {
    let result = await askAgent(question)
    if(result.startsWith(&#39;TOOL:&#39;)){
        let toolName = result.replace(&#39;TOOL:&#39;,&#39;&#39;).trim()
        let toolResult = await runTool(toolName)
        return `工具结果：${toolResult}`
    }
}
接口server.jsimport express from &#39;express&#39;
import { runAgent } from &#39;./services/agentService.js&#39;

let app = express()

app.use(express.json())

app.post(&#39;/agent&#39;,async (req,res)=&gt;{
    let { question } = req.body
    let answer = await runAgent(question)
    res.json({answer})
})

app.listen(3000,()=&gt;{
    console.log(&#39;post 3000&#39;)
})
测试post: 接口 /agentbody: {&#34;question&#34;:&#34;现在几点&#34;}流程：LLM判断 -&gt; 调用 getTime -&gt; 返回时间总结这个项目主要理解什么是Tool，如何调用，但是大模型会匹配不上，主要是理解概念。
